Here, we mainly follow the course of \cite{freeschrei09} and use the following set of vector spherical harmonics:
\begin{align}
{y}_{n,k}^{(1)}\left(\xi\right)&=\xi Y_{n,k}\left(\xi\right),\label{eqn:ynk1}
\\{y}_{n,k}^{(2)}\left(\xi\right)&=\frac{1}{\sqrt{n(n+1)}}\nabla^*_{\xi}Y_{n,k}\left(\xi\right),
\\{y}_{n,k}^{(3)}\left(\xi\right)&=\frac{1}{\sqrt{n(n+1)}}L_{\xi}^*Y_{n,k}\left(\xi\right),\label{eqn:ynk3}
\end{align}
for $n=1,2,\ldots$, and $k=1,\ldots, 2n+1$, with ${y}_{n,k}^{(1)}$ additionally being defined for $n=0$ and $k=1$.

They are complemented by a set of tensorial Legendre polynomials $\mathbf{P}^{(i,i)}_n$ of degree $n$ and type $(i,i)$ that are defined via
\begin{align}
\mathbf{P}^{(1,1)}_n\left(\xi,\eta\right)&=\xi\otimes\eta \,P_n\left(\xi\cdot\eta\right),
\\\mathbf{P}^{(2,2)}_n\left(\xi,\eta\right)&=\frac{1}{{n(n+1)}}\nabla^*_{\xi}\otimes\nabla^*_{\eta}P_n\left(\xi\cdot\eta\right),
\\\mathbf{P}^{(3,3)}_n\left(\xi,\eta\right)&=\frac{1}{{n(n+1)}}L^*_{\xi}\otimes L^*_{\eta}P_n\left(\xi\cdot\eta\right).
\end{align}

_s(\Omega_r)$ is defined as
\begin{align}\label{eqn:sobspace2}
\mathfrak{h}_s(\Omega_r)=\Big\{f\in l^2(\Omega_r) :\|f\|_{\mathfrak{h}_s(\Omega_r)}^2=\sum_{i=1}^2\sum_{n=0_i}^\infty\sum_{k=1}^{2n+1}\left(n+\textnormal{\footnotesize$\frac{1}{2}$}\right)^{2s}\big|({f}_r^{(i)})^\wedge(n,k)\big|^2<\infty\Big\},
\end{align}
where $0_i=0$ if $i=1$ and $0_i=1$ if $i=2$, and $({f}_r^{(i)})^\wedge(n,k)$ denotes the Fourier coefficient of degree $n$, order $k$, and type $i$, i.

The space of band-limited tensorial kernels with maximal degree $N$ is defined as
\small\begin{align}\label{eqn:polnj2}
\mathbf{Pol}_{N}=\left\{\mathbf{K}(x,y)=\sum_{i=1}^2\sum_{n=0_i}^{N}\sum_{k=1}^{2n+1}\mathbf{K}^\wedge(n) {y}^{(i)}_{n,k}\left(\xi\right)\otimes{y}^{(i)}_{n,k}\left(\eta\right):\mathbf{K}^\wedge(n)\in\mathbb{R}\right\}.

The downward continuation operator can be approximated by a bounded operator $t_N:l^2(\Omega_R)\to l^2(\Omega_r)$:
\begin{align}
{t_N[f_1](x)=\int_{\Omega_R}\mathbf{\Phi}_N(x,y) f_1(y)d\omega(y),\quad x\in\Omega_r,}
\end{align}
with
\begin{align}
{\mathbf{\Phi}_N(x,y)=\sum_{i=1}^2\sum_{n=0_i}^{N}\sum_{k=1}^{2n+1}\mathbf{\Phi}_{N}^\wedge(n)\frac{1}{r}{y}^{(i)}_{n,k}\left(\xi\right)\otimes \frac{1}{R}{y}^{(i)}_{n,k}\left(\eta\right).}\label{eqn:scalkernel2}
\end{align}

\label{prop:minsol4}
Assume that all parameters $\tilde{\alpha}_{N,n}$, $\alpha_{N,n}$, and $\beta_N$ are positive. Then there exists unique minimizers $\mathbf{\Phi}_N\in\textnormal{\textbf{Pol}}_{N}$ and $\tilde{\mathbf{\Psi}}_N\in\textnormal{\textbf{Pol}}_{\lfloor\kappa N\rfloor}$ of the functional $\mathcal{F}$ in \eqref{eqn:mineq4} that are determined by $\phi=(\mathbf{\Phi}_N^\wedge(1)\sigma_1,\ldots,\mathbf{\Phi}_N^\wedge(N)\sigma_{N},\tilde{\mathbf{\Phi}}_{N}^\wedge(1),\ldots,\tilde{\mathbf{\Phi}}_{N}^\wedge(\lfloor\kappa N\rfloor))^T$ which solves the linear equations
\begin{align}\label{eqn:lineq4}
\mathbf{M}{\phi}=\alpha,
\end{align}
where 
\begin{align}
\mathbf{M}=\left(\begin{array}{c|c}\mathbf{D}_1+\mathbf{P}_1&-\mathbf{P}_2\\\hline-\mathbf{P}_3&\mathbf{D}_2+\mathbf{P}_4\end{array}\right),
\end{align}
and $\alpha=(\alpha_{N,1},\ldots,\alpha_{N,N},\tilde{\alpha}_{N,1},\ldots,\tilde{\alpha}_{N,\lfloor\kappa N\rfloor})^T$. The diagonal matrices $\mathbf{D}_1$, $\mathbf{D}_2$ are given by 
\begin{align}
\mathbf{D}_1=\textnormal{diag}\left(\frac{\beta_N}{\sigma_n^2}+\alpha_{N,n}\right)_{n=0,\ldots,N}, \qquad\mathbf{D}_2=\textnormal{diag}\big(\tilde{\alpha}_{N,n}\big)_{n=0,\ldots,\lfloor\kappa N\rfloor},
\end{align}
whereas $\mathbf{P}_1$,\ldots, $\mathbf{P}_4$ are submatrices of the Gram matrix $\big(P_{n,m}^\rho\big)_{n,m=0,\ldots, \lfloor\kappa N\rfloor}$. More precisely,
\begin{align}
\mathbf{P}_1=\big(P_{n,m}^\rho\big)_{n,m=0,\ldots,N},&\qquad \mathbf{P}_2=\big(P_{n,m}^\rho\big)_{n=0,\ldots,N\atop m=0,\ldots,N\lfloor\kappa N\rfloor},
\\\mathbf{P}_3=\big(P_{n,m}^\rho\big)_{n=0,\ldots,\lfloor\kappa N\rfloor\atop m=0,\ldots,N},&\qquad\mathbf{P}_4=\big(P_{n,m}^\rho\big)_{n,m=0,\ldots,\lfloor\kappa N\rfloor}.
\end{align}
with
\small\begin{align}
P_{n,m}^\rho=&\frac{(2n+1)(2m+1)}{16\pi^2}\int_{-1}^{1-\rho}P_n\left(t\right)P_m\left(t\right)dt
\\&+\frac{(2n+1)(2m+1)}{16\pi^2n(n+1)m(m+1)}\bigg(\int_{-1}^{1-\rho}(1+t^2)P_n'(t)P_m'(t)dt+\int_{-1}^{1-\rho}(1-t^2)^2P_n''(t)P_m''(t)dt\nonumber
\\&\quad-\int_{-1}^{1-\rho}t(1-t^2)P_n''(t)P_m'(t)dt-\int_{-1}^{1-\rho}t(1-t^2)P_n'(t)P_m''(t)dt\bigg),\nonumber
\end{align}\normalsize
for $n\not=0$ and $m\not=0$. If $n=0$ or $m=0$, then $P_{n,m}^\rho=\frac{(2n+1)(2m+1)}{16\pi^2}\int_{-1}^{1-\rho}P_n\left(t\right)P_m\left(t\right)dt$. By $P_n'$, $P_n''$ we mean the first and second order derivatives of the Legendre polynomials.

\label{prop:loc} 
If $f\in\mathfrak{h}_s(\Omega_r)$, $s\geq 2$, it holds that
